import { StrictMode, useSyncExternalStore } from "react";
import { createRoot } from "react-dom/client";
// eslint-disable-next-line import/no-unresolved -- virtual module generated by the plugin at build time, typed in autoi18n-virtual.d.ts
import { getLocale, getVersion, locales, resolveSupported, setLocale, subscribe } from "virtual:autoi18n";

import { DocumentDashboard } from "./components/DocumentDashboard";

function App() {
  // Re-render on locale switches and on live catalogue updates; getLocale() is read below.
  useSyncExternalStore(subscribe, getVersion, getVersion);
  const locale = getLocale();
  return (
    <>
      <label>
        <span>Language</span>{" "}
        <select value={locale} onChange={(event) => void setLocale(event.target.value)}>
          {locales.map((code) => (
            <option key={code} value={code}>
              {code}
            </option>
          ))}
        </select>
      </label>
      <DocumentDashboard />
    </>
  );
}

// eslint-disable-next-line bun/no-side-effects-on-import -- app entry point; mounting on import is intended
void setLocale(resolveSupported(navigator.languages)).then(() => {
  const root = document.getElementById("root");
  if (!root) throw new Error("Missing #root element");
  createRoot(root).render(
    <StrictMode>
      <App />
    </StrictMode>,
  );
});
